window.__finlexDocLoaded(212,{"id":212,"articles":[{"id":5419,"no":"问1","heading":"问：投资方的联营企业作为合并方发生同一控制下企业合并的情况下，依据同一控制下企业合并的会计处理原则，联营企业于合并日需将取得的被合并方净资产的入账价值与合并对价账面价值之间的差额调整资本公积等，并视同自最终控制方开始控制被合并方时起即控制被","text":"【发布日期：2026-06-18】\n答：根据《企业会计准则第2号——长期股权投资》第十一条并参考应用指南，对于被投资单位除净损益、其他综合收益以及利润分配以外所有者权益的其他变动，应当按持股比例计算应享有的份额，调整长期股权投资的账面价值，同时调整资本公积（其他资本公积）。当联营企业发生同一控制下企业合并时，投资方应基于联营企业合并日的所有者权益净变动额计算其享有的净资产份额，相应调整长期股权投资的账面价值，同时调整资本公积（其他资本公积）；但是对于联营企业因同一控制下企业合并还原被合并方合并日前留存收益、其他综合收益等引发的资本公积与留存收益、其他综合收益等的重分类调整，投资方无需就此对长期股权投资的账面价值进行调整。","seq":0},{"id":5420,"no":"问2","heading":"问：上市公司乙公司是甲公司的联营企业。乙公司向员工以非公开发行的方式授予限售期为3年的限制性股票用于股权激励，并完成股东登记手续。乙公司与员工约定，自授予日起，员工服务满3年后可一次性解锁股份；限售期限内离职的，乙公司按员工认购价格回购相应","text":"【发布日期：2023-01-03】\n答：按照《企业会计准则解释第7号》（财会〔2015〕19号）等相关规定，对于此类授予限制性股票的股权激励计划，向职工发行的限制性股票按有关规定履行了注册登记等增资手续的，企业应当根据收到职工缴纳的认股款确认股本和资本公积（股本溢价），同时就回购义务确认负债（作收购库存股处理）。本问题中的乙公司增发限制性股票时，按照《企业会计准则解释第7号》等进行会计处理，其财务报表中的净资产没有发生变化。对于投资方甲公司而言，在乙公司增发限制性股票时，不会产生《企业会计准则第2号——长期股权投资》（财会〔2014〕14号）第十一条所规定的“被投资单位除净损益、其他综合收益和利润分配以外所有者权益的其他变动”，因此本问题中的甲公司在乙公司增发限制性股票时，不应当将对乙公司的长期股权投资按照股权被动稀释进行会计处理。","seq":1},{"id":5421,"no":"问3","heading":"问：投资方与其联营企业或合营企业之间发生投出或出售资产交易（构成业务的除外）而产生的未实现内部交易损益，投资方在编制合并财务报表时应如何抵销？","text":"【发布日期：2023-01-03】\n答：按照《企业会计准则第2号——长期股权投资》（财会〔2014〕14号）、《企业会计准则第33号——合并财务报表》（财会〔2014〕10号）等相关规定，对于投资方与其联营企业或合营企业之间发生投出或出售资产交易（构成业务的除外）而产生的未实现内部交易损益中归属于投资方的部分，投资方在编制合并财务报表时，应当在个别财务报表抵销的基础上进行调整。对于投资方向联营企业或合营企业投出或出售资产的顺流交易而产生的未实现内部交易损益中归属于投资方的部分，投资方在编制合并财务报表时，在个别财务报表处理的基础上，应当对有关未实现的收入和成本或资产处置损益等中归属于投资方的部分予以抵销，并相应调整相关投资收益；对于联营企业或合营企业向投资方投出或出售资产的逆流交易而产生的未实现内部交易损益中归属于投资方的部分，投资方在编制合并财务报表时，在个别财务报表处理的基础上，应当对有关资产账面价值中包含的未实现内部交易损益中归属于投资方的部分予以抵销，并相应调整长期股权投资的账面价值。投资方与其联营企业或合营企业之间发生的无论是顺流交易还是逆流交易产生的未实现内部交易损失，其中属于所转让资产发生减值损失的，有关的未实现内部交易损失在合并财务报表中不应予以抵销。","seq":2},{"id":5422,"no":"问4","heading":"问：联营企业或合营企业自2021年1月1日起执行新收入准则、新金融工具准则、新租赁准则（以下简称“新准则”）。投资方执行新准则的时间早于其联营企业或合营企业，但在联营企业或合营企业尚未执行新准则的期间，因客观条件限制，投资方采用权益法核算时","text":"【发布日期：2021-11-02】\n答：根据新收入准则、新金融工具准则、新租赁准则（以下简称“新准则”）的实施时间安排和衔接规定，自2021年1月1日起所有执行企业会计准则的企业（根据有关规定暂缓执行相关新准则的除外）均须执行新准则。投资方的联营企业或合营企业因2021年1月1日起执行新准则而仅对2021年财务报表的期初数进行调整的，投资方在采用权益法核算时应当相应调整其2021年财务报表的期初数，并在其财务报表附注中披露这一事实。","seq":3}]});
